def test_fd_partial_write_rewound(plugin, tmp_path):
    hooks = plugin.Hooks(plugin.Policy(), Mock())
    calls = []

    def download(conf, url, fd):
        calls.append(1)
        plugin.os.write(fd, b"partial" if len(calls) == 1 else b"ok")
        if len(calls) == 1:
            raise RuntimeError("Curl error (28): Timeout")

    with (tmp_path / "out").open("w+b") as stream:
        stream.write(b"prefix")
        stream.flush()
        hooks.exceptions(download, (RuntimeError,), fd_index=2)(
            None, "url", stream.fileno()
        )
        stream.seek(0)
        assert stream.read() == b"prefixok"


